TfLiteStatus GetImage(int image_width, int image_height, int channels, int8_t* image_data, int8_t type)
{
    const unsigned char *p_data = NULL;

    if (0 == type)
    {
        // Person image
        p_data = g_person_image_data;
    }
    else if (1 == type)
    {
        // No person image
        p_data = g_no_person_image_data;
    }
    else
    {
        // Unsupported type
        return kTfLiteError;
    }

    for (int i = 0; i < image_width * image_height * channels; ++i) {
      image_data[i] = (int8_t)(p_data[i] - 128);
    }

    return kTfLiteOk;
}
